inventory=[]
for file in sorted((ROOT/'wiki/sources').glob('*.md')):
 text=file.read_text()
 if re.search(r'\bavocado(?:s)?\b',text,re.I) and file.stem!='index':inventory.append(file)
for key in decisions:
 f=ROOT/f'wiki/sources/{key}.md'
 if f.exists() and f not in inventory:inventory.append(f)
