 records.append(dict(source_id=key,path=str(f.relative_to(ROOT)),sha256=sha(f),disposition=d[0],reason=d[1],local_record_content_checked=True,primary_verified=d[2] is not None,primary_ref=str(A.relative_to(ROOT)/d[2]) if d[2] else None,locator=d[3],routing='Ingredient candidate' if d[0]=='used/extracted' else 'Private avocado source-scope record; central source/registry ownership preserved',content_hits=[line[:800] for line in text.splitlines() if re.search(r'\bavocado(?:s)?\b',line,re.I)][:12]))
