 file=ROOT/'data/evidence'/name;rs=list(csv.DictReader(file.open()));selected=[dict(csv_row=i+2,**r) for i,r in enumerate(rs) if 'avocado' in r.get(field,'').lower()]
 if name.startswith('category1_autonomy'):selected=[dict(csv_row=i+2,**r) for i,r in enumerate(rs) if r['source_id']=='yoplac2026-peruvian-avocado-metals-health-risk']
 datasets.append(dict(path=str(file.relative_to(ROOT)),sha256=sha(file),matching_field=field,matching_rows=len(selected),rows=selected,disposition='Held: original raw GEMS identity/censoring' if name.startswith('who') else 'Context-only finished mixed foods' if 'compliance' in name else 'Reject extraction: soil Cd routed to fruit; see correction' if 'autonomy' in name else 'No avocado-specific product-label rows; generic category label is not avocado evidence'))
